let waveActive=false,waveGeneration=0,wavePending=null,waveApplied={},waveSeen=new Set();
function stopWave(){$('waveStart').disabled=false;waveActive=false;waveGeneration++;wavePending=null;}
function waveSettings(){const energy=Number($('waveEnergy').value),fun=Number($('waveFun').value);if($('waveMood').checked&&(!$('waveEnergy').value||!$('waveFun').value||!Number.isFinite(energy)||!Number.isFinite(fun)))throw new Error(OrbitaI18n.t('Укажи числовые значения энергии и веселья.'));return {mood:$('waveMood').checked,energy,fun};}
