function fillWave(){
 if(!waveActive)return Promise.resolve();if(wavePending)return wavePending;
 const generation=waveGeneration,session=sessionTicket;
 const task=(async()=>{try{
  for(let attempt=0;attempt<3;attempt++){
   const rows=await call('wave',waveApplied);
   if(!waveActive||generation!==waveGeneration||session!==sessionTicket)return;
   const batchSeen=new Set(waveSeen);const fresh=rows.filter(t=>{if(batchSeen.has(t.id))return false;batchSeen.add(t.id);return true;});
   if(fresh.length){for(const t of fresh){waveSeen.add(t.id);queue.push(t);}updateQueue();if(view==='wave'||view==='queue'){visible=queue;render();}$('waveStatus').textContent=OrbitaI18n.t('В очереди потока: ')+OrbitaI18n.count(queue.length,'track');return;}
  }
  $('waveStatus').textContent=OrbitaI18n.t('Звук пока не прислал новых треков. Можно перезапустить поток.');
 }catch(e){if(generation===waveGeneration){$('waveStatus').textContent=OrbitaI18n.message(e.message);notice(e.message);}}
 finally{if(generation===waveGeneration)wavePending=null;}})();wavePending=task;return task;
}
