function paintArtistAlbums(){const box=$('artistAlbums');if(!box)return;box.replaceChildren();box.hidden=view!=='artist';if(view!=='artist')return;
 const tabs=element('div','artistTabs');tabs.setAttribute('role','group');tabs.setAttribute('aria-label',OrbitaI18n.t('Раздел исполнителя'));for(const [mode,title] of [['tracks',OrbitaI18n.t('Все треки')],['albums',OrbitaI18n.t('Альбомы')]]){const b=element('button','',title);b.setAttribute('aria-pressed',String(artistMode===mode));b.onclick=()=>switchArtistMode(mode);tabs.append(b);}box.append(tabs);
 if(artistMode!=='albums')return;box.append(element('p','hint',OrbitaI18n.t('От новых к старым')));const list=element('div','artistAlbumList');for(const a of artistAlbums){const card=element('button','artistAlbumEntry');card.append(cover(a.cover),element('strong','',a.title),element('small','',a.year?String(a.year):OrbitaI18n.t('Год не указан')));card.onclick=()=>openAlbum({albumId:a.id,album:a.title,artist:$('sectionTitle').textContent});list.append(card);}box.append(list);if(!artistAlbums.length)box.append(element('p','hint',OrbitaI18n.t('Альбомы пока не загружены')));}

window.desktop.onQuality?.(q=>{if(!['hifi','high','mid'].includes(q))return;$('quality').value=q;$('quality').onchange();});

// Queue editing changes entry indices, never remote track IDs.
function enqueue(t,next=false){const at=next?(index>=0?index+1:0):queue.length;queueOrder.insert(at);queue.splice(at,0,t);if(next)queueOrder.schedule(at);if(index>=at)index++;updateQueue();notice(next?OrbitaI18n.t('Следующим: ')+t.title:OrbitaI18n.t('В конец очереди: ')+t.title,'success');return at;}
function moveQueue(from,to){if(!Number.isInteger(from)||!Number.isInteger(to)||from<0||to<0||from>=queue.length||to>=queue.length||from===to)return;queueOrder.move(from,to);const item=queue.splice(from,1)[0];queue.splice(to,0,item);if(index>=0)index=queueMovedIndex(index,from,to);updateQueue();}
function resetNow(){pendingResume=0;$('nowTitle').textContent=OrbitaI18n.t('Выбери, что послушать');$('nowArtist').replaceChildren();const c=cover('');c.id='nowCover';$('nowCover').replaceWith(c);$('elapsed').textContent=$('duration').textContent='0:00';$('seek').value=0;$('actualQuality').textContent='—';publishPlayerState();}
function removeQueue(at){if(!Number.isInteger(at)||at<0||at>=queue.length)return;const selected=at===index,playing=!audio.paused,t=queue[at];queueOrder.remove(at);queue.splice(at,1);if(at<index)index--;else if(selected){playTicket++;audio.pause();audio.removeAttribute('src');audio.load();pendingResume=0;index=queue.length?Math.min(at,queue.length-1):-1;if(index>=0){queueOrder.visit(index);paintRestored();}else resetNow();}updateQueue();if(selected&&playing&&index>=0)playAt(index);notice(OrbitaI18n.t('Убрано из очереди: ')+t.title,'success');}
async function removeLibrary(t){try{localTracks=await call('local-remove',t.id);$('localCount').textContent=localTracks.length;for(let i=queue.length-1;i>=0;i--)if(queue[i].id===t.id)removeQueue(i);if(view==='local')renderLocal();notice(OrbitaI18n.t('Убрано из библиотеки. Файл остался на диске.'),'success');}catch(e){notice(e.message);}}
function jumpCurrent(){if(index<0)return;queueLimit=Math.max(queueLimit,Math.ceil((index+1)/200)*200);visible=queue;render();const row=$('rows').querySelector('[data-row-index="'+index+'"]');row?.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});row?.focus({preventScroll:true});}
$('jumpCurrent').onclick=jumpCurrent;
$('clearNext').onclick=()=>{stopWave();const last=index>=0?index:-1;queue.splice(last+1);queueOrder.trim(last);updateQueue();notice(last>=0?OrbitaI18n.t('Следующие треки убраны.'):OrbitaI18n.t('Очередь очищена.'),'success');};
let menuAnchor=null;
function closeTrackMenu(focus=false){const box=$('trackMenu');if(!box)return;box.hidden=true;box.replaceChildren();if(focus&&menuAnchor?.isConnected)menuAnchor.focus();menuAnchor=null;}
function openTrackMenu(t,i,anchor){closeTrackMenu();menuAnchor=anchor;const box=$('trackMenu');const action=(text,fn,disabled=false)=>{const b=element('button','',text);b.disabled=disabled;b.setAttribute('role','menuitem');b.onclick=()=>{closeTrackMenu();fn();};box.append(b);};
 action(OrbitaI18n.t('Играть следующим'),()=>enqueue(t,true));action(OrbitaI18n.t('В конец очереди'),()=>enqueue(t,false));
 if(view==='queue'){action(OrbitaI18n.t('Выше'),()=>moveQueue(i,i-1),i===0);action(OrbitaI18n.t('Ниже'),()=>moveQueue(i,i+1),i===queue.length-1);action(OrbitaI18n.t('Убрать из очереди'),()=>removeQueue(i));}
 if(t.source==='local'&&view==='local')action(OrbitaI18n.t('Убрать из библиотеки'),()=>removeLibrary(t));
 box.hidden=false;const r=anchor.getBoundingClientRect();box.style.left=Math.max(8,Math.min(r.right-240,innerWidth-248))+'px';box.style.top=Math.max(8,Math.min(r.bottom+5,innerHeight-box.offsetHeight-12))+'px';box.querySelector('button:not(:disabled)')?.focus();
}
document.addEventListener('pointerdown',e=>{if(!$('trackMenu').hidden&&!$('trackMenu').contains(e.target)&&e.target!==menuAnchor)closeTrackMenu();});
$('trackMenu').addEventListener('keydown',e=>{const buttons=[...$('trackMenu').querySelectorAll('button:not(:disabled)')],at=buttons.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();closeTrackMenu(true);}else if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(at+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();}else if(e.key==='Tab')closeTrackMenu();});
window.addEventListener('resize',()=>closeTrackMenu());window.addEventListener('scroll',()=>closeTrackMenu(),true);
$('toastClose').onclick=()=>{$('toast').hidden=true;};$('dismissError').onclick=()=>{$('playbackAlert').hidden=true;};$('errorSettings').onclick=login;$('retryPlayback').onclick=()=>{if(queue[index])playAt(index,playbackTime());};

// Repaint labels only. Keep the Audio element, queue, selection and web session alive.
window.addEventListener('orbita-language',()=>{
 const scroll=window.scrollY,folderScroll=$('folders').scrollTop;
 const titles={liked:'Любимые треки',queue:'Очередь',local:'Библиотека ПК',wave:'В твоём потоке',search:'Результаты поиска'};
 if(titles[view])$('sectionTitle').textContent=OrbitaI18n.t(titles[view]);
 $('sectionCaption').textContent=OrbitaI18n.message($('sectionCaption').textContent);
 $('search').placeholder=OrbitaI18n.t(view==='local'?'Поиск по файлам на этом ПК':'Найти трек или исполнителя в Звуке');
 if(!connected)$('account').textContent=OrbitaI18n.t('Аккаунт не подключён');
 $('artistBack').textContent=OrbitaI18n.t('← Назад');
 for(const option of $('eqPreset').options)option.textContent=OrbitaI18n.t(option.value);
 syncEqUI();document.querySelectorAll('.eqBand input').forEach((input,i)=>input.setAttribute('aria-label',OrbitaI18n.t('Частота ')+EQ_FREQ[i]+OrbitaI18n.t(' Гц')));document.querySelector('.pauseIcon')?.setAttribute('aria-label',OrbitaI18n.t('Пауза'));render();if(view==='local')renderFolders();
 $('nowHeart').dataset.heartKey='';paintCurrentHeart();if(queue[index])paintNowArtist(queue[index]);else $('nowTitle').textContent=OrbitaI18n.t('Выбери, что послушать');
 settingsButton();paintNavigation();
 $('waveStatus').textContent=waveActive?OrbitaI18n.t('В очереди потока: ')+OrbitaI18n.count(queue.length,'track'):OrbitaI18n.t('Готов к запуску');
 $('localStatus').textContent='';
 if(lastNotice&&(!$('notice').hidden||!$('playbackAlert').hidden))notice(lastNotice.s,lastNotice.kind);else $('toast').hidden=true;
 closeTrackMenu();window.scrollTo(0,scroll);$('folders').scrollTop=folderScroll;publishPlayerState();
});

// Publish the audio clock directly, including when the main window is hidden.
setInterval(()=>{if(!audio.paused)publishPlayerState();},500);
